        .with_custom_protocol("wry".into(), move |request| {
            let path = request.uri().path();
            let resource_name =
                resource_name_for_log(path).unwrap_or("<redacted>");
            let resource = match resolve_resource_path(&resource_path, path) {
                Ok(resource) => resource,
                Err(e) => {
                    tracing::warn!(
                        target: "msinsight_platform",
                        event = "resource_read_failed",
                        resource_name,
                        reason = "invalid_path"
                    );
                    return Err(wry024::Error::Io(e));
                }
            };
            let content = match read(resource) {
                Ok(content) => content.into(),
                Err(e) => {
                    tracing::warn!(
                        target: "msinsight_platform",
                        event = "resource_read_failed",
                        resource_name,
                        reason = "read_failed"
                    );
                    return Err(wry024::Error::Io(e));
                }
            };

            let mimetype = extract_mimetype(path);
            tracing::debug!(
                target: "msinsight_platform",
                event = "resource_read_succeeded",
                resource_name,
                response_mime = mimetype
            );

            Response::builder()
                .header(CONTENT_TYPE, mimetype)
                .body(content)
                .map_err(Into::into)
        })
        .with_url
